CREATE TABLE admin_users (id INTEGER PRIMARY KEY CHECK(id=1), password_hash TEXT NOT NULL, salt TEXT NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE assets (id TEXT PRIMARY KEY, sha256 TEXT NOT NULL UNIQUE, master_path TEXT NOT NULL, filename TEXT NOT NULL, format TEXT NOT NULL, bytes INTEGER NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE renditions (id TEXT PRIMARY KEY, asset_id TEXT NOT NULL REFERENCES assets(id), width INTEGER NOT NULL, height INTEGER NOT NULL, format TEXT NOT NULL, path TEXT NOT NULL);
CREATE TABLE photos (id INTEGER PRIMARY KEY AUTOINCREMENT, asset_id TEXT REFERENCES assets(id), title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT 'daily', date TEXT, captured_raw TEXT, offset_time TEXT, equipment_id TEXT, exif TEXT NOT NULL DEFAULT '{}', featured INTEGER NOT NULL DEFAULT 0, featured_order INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','trash')), position TEXT NOT NULL DEFAULT 'center', is_demo INTEGER NOT NULL DEFAULT 0, demo_data TEXT, author TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_photos_status_date_id ON photos(status,date,id);
CREATE TABLE collections (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', story TEXT NOT NULL DEFAULT '', label TEXT NOT NULL DEFAULT '', english TEXT NOT NULL DEFAULT '', quote TEXT NOT NULL DEFAULT '', cover_photo_id INTEGER REFERENCES photos(id), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), sort_order INTEGER NOT NULL DEFAULT 0, is_demo INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE collection_photos (collection_id INTEGER NOT NULL REFERENCES collections(id) ON DELETE CASCADE, photo_id INTEGER NOT NULL REFERENCES photos(id), sort_order INTEGER NOT NULL, PRIMARY KEY(collection_id,photo_id));
CREATE INDEX idx_collection_photos_photo ON collection_photos(photo_id);
CREATE TABLE import_jobs (id TEXT PRIMARY KEY, filename TEXT NOT NULL, source_type TEXT NOT NULL, source_root TEXT, source_path TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', error TEXT, photo_id INTEGER REFERENCES photos(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_import_jobs_status ON import_jobs(status,created_at);
CREATE TABLE import_scans (id TEXT PRIMARY KEY, root TEXT NOT NULL, folder TEXT NOT NULL, files TEXT NOT NULL, created_at TEXT NOT NULL);
